const { useState } = React;

const QUESTIONS = [
  {
    id: "q1",
    prompt: "Which of these are statically typed languages?",
    help: "Hint: select all that apply. Statically typed languages check types at compile time.",
    choices: [
      { id: "a", label: "TypeScript" },
      { id: "b", label: "Python" },
      { id: "c", label: "Rust" },
      { id: "d", label: "JavaScript" },
    ],
    correct: ["a", "c"],
  },
  {
    id: "q2",
    prompt: "Which languages run natively in a web browser?",
    choices: [
      { id: "a", label: "JavaScript" },
      { id: "b", label: "WebAssembly" },
      { id: "c", label: "Ruby" },
      { id: "d", label: "Go" },
    ],
    correct: ["a", "b"],
  },
  {
    id: "q3",
    prompt: "Which languages are commonly used for systems programming?",
    choices: [
      { id: "a", label: "C" },
      { id: "b", label: "PHP" },
      { id: "c", label: "Rust" },
      { id: "d", label: "C++" },
    ],
    correct: ["a", "c", "d"],
  },
];

function Question({ question, index, selected, onToggle }) {
  return (
    <div className="form-field">
      <label className="question-label">
        <span className="question-number">{index + 1}.</span>
        {question.prompt}
      </label>
      {question.help && <span className="help-text">{question.help}</span>}
      <div className="choices" role="group" aria-label={question.prompt}>
        {question.choices.map((choice) => {
          const isSelected = selected.includes(choice.id);
          return (
            <label
              key={choice.id}
              className={`choice ${isSelected ? "selected" : ""}`}
            >
              <input
                type="checkbox"
                checked={isSelected}
                onChange={() => onToggle(question.id, choice.id)}
              />
              <span className="choice-label">{choice.label}</span>
            </label>
          );
        })}
      </div>
    </div>
  );
}

function Quiz() {
  const [answers, setAnswers] = useState({ q1: [], q2: [], q3: [] });
  const [result, setResult] = useState(null);

  const toggle = (qid, cid) => {
    setAnswers((prev) => {
      const current = prev[qid];
      const next = current.includes(cid)
        ? current.filter((c) => c !== cid)
        : [...current, cid];
      return { ...prev, [qid]: next };
    });
    setResult(null);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let score = 0;
    QUESTIONS.forEach((q) => {
      const sel = [...answers[q.id]].sort().join(",");
      const correct = [...q.correct].sort().join(",");
      if (sel === correct) score += 1;
    });
    setResult({ score, total: QUESTIONS.length });
  };

  return (
    <form className="quiz-card" onSubmit={handleSubmit}>
      <div className="quiz-header">
        <h1>Computer Languages Quiz</h1>
        <p>Test your knowledge — multiple answers may be correct.</p>
      </div>
      {QUESTIONS.map((q, i) => (
        <Question
          key={q.id}
          question={q}
          index={i}
          selected={answers[q.id]}
          onToggle={toggle}
        />
      ))}
      <div className="actions">
        <button type="submit" className="submit-btn">
          Submit
        </button>
      </div>
      {result && (
        <div className="results">
          <h2>
            You scored <span className="score">{result.score} / {result.total}</span>
          </h2>
          <p>
            {result.score === result.total
              ? "Perfect — you nailed it!"
              : "Review the questions and try again."}
          </p>
        </div>
      )}
    </form>
  );
}

